mapper.select:
select from oa_feedback f where f.del_flag = '0'
and f.submitter_id = #{currentUserId}
and f.type = #{type}
and f.status = #{status}
and (f.ticket_no like concat('%', #{keyword}, '%') or f.title like concat('%', #{keyword}, '%') or f.content like concat('%', #{keyword}, '%'))
and f.submit_time >= concat(#{beginTime}, ' 00:00:00')
and f.submit_time <= concat(#{endTime}, ' 23:59:59')
order by f.submit_time desc, f.feedback_id desc

select from oa_feedback f where f.del_flag = '0'
and f.type = #{type}
and f.status = #{status}
and f.submitter_id = #{submitterId}
and f.is_anonymous = #{isAnonymous}
and (f.ticket_no like concat('%', #{keyword}, '%') or f.title like concat('%', #{keyword}, '%') or f.content like concat('%', #{keyword}, '%') or f.submitter_name like concat('%', #{keyword}, '%'))
and f.submit_time >= concat(#{beginTime}, ' 00:00:00')
and f.submit_time <= concat(#{endTime}, ' 23:59:59')
order by f.status asc, f.submit_time desc, f.feedback_id desc

select 
from oa_feedback f
where f.feedback_id = #{feedbackId}

mapper.update:
update oa_feedback
set del_flag = '2', update_time = sysdate()
where feedback_id = #{feedbackId}
  and submitter_id = #{submitterId}
  and status = '0'
  and del_flag = '0'

